package com.bnfix.ubm.domains.manager;
import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface ManagerRepository extends JpaRepository<Manager,Long> { List<Manager> findByCompanyId(Long id); @Query("select m from Manager m join fetch m.account join fetch m.company c where m.account.id=:id and m.active=true and c.active=true order by m.createdAt desc,m.id desc") Optional<Manager> findActiveByAccountId(@Param("id") UUID id); @Query("select m from Manager m where m.company.cnpj.value=:cnpj") List<Manager> findByCNPJ(@Param("cnpj") String cnpj); @Query("select m from Manager m join fetch m.account a join fetch m.company c where lower(a.email)=lower(:email) and c.id=:id") Optional<Manager> findByEmailAndCompanyId(@Param("email") String email,@Param("id") Long companyId); @Query("select m from Manager m join fetch m.account a join fetch m.company c where lower(a.email)=lower(:email) and m.active=true and c.active=true order by m.createdAt desc,m.id desc") List<Manager> findActiveByEmail(@Param("email") String email); @Modifying @Query("update Manager m set m.active=false where m.company.id=:id and m.active=true") int deactivateByCompanyId(@Param("id") Long companyId); }
